/**
 * PRINTER'S ORNAMENTS AND RUBBER STAMPS.
 *
 * Cut from the supplied engraved sheet. The corner and the dividers are ALPHA
 * MASKS, like the icon set, so CSS fills them — brass on a dark frame, ink on
 * stock. The top-left corner is the only one shipped; the other three are the
 * same piece mirrored in CSS, which guarantees they match.
 *
 * The two stamp frames are already INKED (stamp-bad, stamp-good) because they
 * are drawn with border-image, which paints an image's own colours and cannot
 * be recoloured. Their rough edge and speckle are the point: a stamp that was
 * a 2px CSS border read as a form field, not as ink.
 */
export const ORN_CORNER = 'data:image/webp;base64,';
export const ORN_DIVIDER_LEAF = 'data:image/webp;base64,';
export const ORN_DIVIDER_WHEAT = 'data:image/webp;base64,';
export const STAMP_FRAME_BAD = 'data:image/webp;base64,';
export const STAMP_FRAME_GOOD = 'data:image/webp;base64,';
